const rows = $json.values || [];
const unsynced = [];

rows.forEach((row, i) => {
  const barcode = row[0];
  if (barcode === undefined || barcode === null || String(barcode).trim() === '') return;

  const ready = row[5]; // kolom F
  if (String(ready).trim().toLowerCase() !== 'ya') return; // belum ditandai siap -- skip

  const status = row[6]; // kolom G (geser dari F)
  if (status !== undefined && status !== null && String(status).trim() !== '') return; // sudah pernah sync

  unsynced.push({ rowNumber: i + 2, data: row });
});

if (unsynced.length === 0) return [];
return [{ json: { unsynced } }];

const response = $json;
const row = (response.values && response.values[0]) || [];
const fileId = row[1];

if (!fileId || String(fileId).trim() === '') {
  return []; // ActiveCutoff kosong (masa transisi antar hari) -- PENDING, coba lagi jadwal berikutnya
}

return [{ json: { id: fileId } }];

function toNumberIfPossible(v) {
  if (v === undefined || v === null || v === '') return v;
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return (!isNaN(n) && String(v).trim() !== '') ? n : v;
}

function currentTime() {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Makassar',
    hour: '2-digit', minute: '2-digit', hour12: false
  }).formatToParts(new Date());
  const get = type => parts.find(p => p.type === type).value;
  return `${get('hour')}:${get('minute')}`;
}

const unsynced = $('Filter Unsynced Penerimaan').first().json.unsynced;
const lastRowData = $json.values || [];
const nextRow = lastRowData.length + 1;
const jam = currentTime();

const values = unsynced.map(item => {
  const d = item.data;
  return [
    toNumberIfPossible(d[0]), // A Barcode
    d[1],                     // B Description
    toNumberIfPossible(d[2]), // C Alamat
    '', '', '',               // D,E,F Awal/rekap/gap -- kosong
    toNumberIfPossible(d[3]), // G PC
    toNumberIfPossible(d[4]), // H Jumlah
    '', '',                   // I,J -- kosong
    jam,                      // K -- jam saat ini, misal "14:00"
  ];
});

return [{ json: { values, nextRow, rowNumbers: unsynced.map(u => u.rowNumber) } }];

