const unsynced = $('Filter Unsynced Alamat').first().json.unsynced;
const withReplacement = unsynced.filter(item => {
  const old = item.data[4];
  return old !== undefined && old !== null && String(old).trim() !== '';
});

if (withReplacement.length === 0) return [];
return [{ json: { withReplacement } }];

const withReplacement = $('Check Has Replacements').first().json.withReplacement;
const columnD = ($json.values || []).map(r => (r[0] !== undefined && r[0] !== null) ? String(r[0]).trim() : '');
const PREFIXES = ['EKS', 'EX', 'EK', 'EXS'];

const toMark = [];
const notFound = [];

for (const item of withReplacement) {
  const oldAlamat = String(item.data[4]).trim();
  const rowIndex = columnD.findIndex(v => v === oldAlamat);
  if (rowIndex === -1) {
    notFound.push(oldAlamat);
    continue;
  }
  const rowNumber = rowIndex + 1;
  let chosenPrefix = PREFIXES[PREFIXES.length - 1];
  for (const prefix of PREFIXES) {
    const candidate = `${prefix} ${oldAlamat}`;
    if (!columnD.includes(candidate)) { chosenPrefix = prefix; break; }
  }
  toMark.push({ rowNumber, newValue: `${chosenPrefix} ${oldAlamat}` });
}

return [{ json: { toMark, notFound } }];

function toNumberIfPossible(v) {
  if (v === undefined || v === null || v === '') return v;
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return (!isNaN(n) && String(v).trim() !== '') ? n : v;
}

const rows = $json.values || [];

// Copy 1:1, tanpa filter, biar row count Sheet1 persis sama dengan sheet Alamat
const valuesABC = rows.map(row => [ toNumberIfPossible(row[0]), row[1], row[2] ]);
const valuesJ = rows.map(row => [ row[10] ]);

return [{ json: { valuesABC, valuesJ } }];

function toNumberIfPossible(v) {
  if (v === undefined || v === null || v === '') return v;
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return (!isNaN(n) && String(v).trim() !== '') ? n : v;
}

const EKS_PATTERN = /^(EKS|EX|EK|EXS)\s/;
const alamatRows = $('Read Full Alamat Sheet').first().json.values || [];

// Sumber (Alamat!B2:L..): index0=Barcode,1=Description,2=Alamat,...,10=Personel
const activeByBarcode = new Map();
for (const row of alamatRows) {
  const barcode = row[0];
  if (barcode === undefined || barcode === null || String(barcode).trim() === '') continue;
  const alamat = row[2];
  if (alamat !== undefined && alamat !== null && EKS_PATTERN.test(String(alamat).trim())) continue; // skip alamat obsolete
  const key = String(barcode).trim();
  activeByBarcode.set(key, { barcode, description: row[1], alamat, personel: row[10] });
}

const existingRowsRaw = $json.values || [];
const existingBarcodes = new Set(
  existingRowsRaw.map(r => (r[0] !== undefined && r[0] !== null) ? String(r[0]).trim() : '').filter(Boolean)
);

const nextRow = existingRowsRaw.length + 2; // range baca mulai A2

const newRows = [];
const formulas = [];
let rowCounter = nextRow;
for (const [key, item] of activeByBarcode) {
  if (existingBarcodes.has(key)) continue;
  newRows.push([ toNumberIfPossible(item.barcode), item.personel, item.description, item.alamat ]);
  formulas.push([ `=VLOOKUP(A${rowCounter};PIVOT!B:C;2;0)` ]);
  rowCounter++;
}

if (newRows.length === 0) return [];

return [{ json: { newRows, formulas, nextRow, count: newRows.length } }];

