const item = $input.item;
const binary = { ...item.binary, data: { ...item.binary.data, fileName: 'Laporan Stok Opname Warehouse.xlsx' } };
return [{ json: item.json, binary }];

function colToIndex(col) {
  let idx = 0;
  for (const ch of col.toUpperCase()) idx = idx * 26 + (ch.charCodeAt(0) - 64);
  return idx - 1;
}
function indexToCol(idx) {
  let n = idx + 1, s = '';
  while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); }
  return s;
}
const row = ($json.values && $json.values[0]) || [];
const colE = row[1] || 'E';
const colF = indexToCol(colToIndex(colE) + 1);
const colG = indexToCol(colToIndex(colE) + 2);
return [{ json: { colF, colG } }];

const flagsRow = ($json.values && $json.values[0]) || [];
const PERSONEL_MAP = { 0: 'Rama', 1: 'Saiful', 2: 'Rengga', 3: 'Sahar' };
const COLS = ['L', 'M', 'N', 'O'];

const pending = [];
for (let i = 0; i < 4; i++) {
  const flag = flagsRow[i];
  if (String(flag || '').trim() !== 'Kirim') continue;
  pending.push({ json: { personelNum: i + 1, personelName: PERSONEL_MAP[i], colLetter: COLS[i] } });
}
return pending;

function toNumberIfPossible(v) {
  if (v === undefined || v === null || v === '') return v;
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return (!isNaN(n) && String(v).trim() !== '') ? n : v;
}

const items = $input.all();
const output = [];
for (const item of items) {
  const rows = item.json.values || [];
  const correctionRows = [];
  for (const row of rows) {
    const barcode = row[0];
    if (barcode === undefined || barcode === null || String(barcode).trim() === '') continue;
    const jNum = Number(row[9]);
    if (isNaN(jNum) || jNum >= 0) continue; // cuma yang minus (barang kosong)
    correctionRows.push([ toNumberIfPossible(row[0]), row[1], row[2], '', '', '', toNumberIfPossible(row[6]), toNumberIfPossible(jNum) ]);
  }
  output.push({ json: { correctionRows } });
}
return output;

